scripts.script:
import groovy.json.JsonOutput
import groovy.json.JsonSlurper
import java.security.MessageDigest
import java.util.zip.ZipFile

// Reduces the CycloneDX SBOM of the module's whole Maven graph to the files its zip delivers.
// No less-than character in this script: maven-release-plugin's POM rewrite replaces the first run of two or more whitespace characters after one, up to the next greater-than, with one space, which can join script lines.
// A delivered file is identified by SHA-256 among the components of the graph, then by SHA-256 among the contents of
// the zips of the graph, then by artifactId (bare or followed by the version) among the components whose artifact
// has the file's extension.
// FAIL_ON_GAPS: an unidentified, ambiguous, differing or duplicate delivered file fails the build when true.
final boolean FAIL_ON_GAPS = false
final List DELIVERED_EXTENSIONS = ['.jar', '.war']

String digest(String algorithm, InputStream input) {
  MessageDigest md = MessageDigest.getInstance(algorithm)
  byte[] buffer = new byte[65536]
  int read
  while ((read = input.read(buffer)) > 0) {
    md.update(buffer, 0, read)
  }
  return md.digest().encodeHex().toString()
}

List hashesOf(Closure opener) {
  return ['SHA-256', 'SHA-512'].collect { algorithm ->
    InputStream input = opener()
    try {
      [alg: algorithm, content: digest(algorithm, input)]
    } finally {
      input.close()
    }
  }
}

// The zip the module delivers: its main artifact, or its attached artifact with no classifier.
File deliverableZip() {
  List zips = ([project.artifact] + project.attachedArtifacts).findAll {
    !it.classifier && it.file?.name?.endsWith('.zip')
  }*.file.unique(false)
  if (zips.size() == 1) {
    return zips[0]
  }
  throw new IllegalStateException('SBOM: expected one zip with no classifier among the artifacts of '
      + project.artifactId + ', found ' + zips*.name)
}

File zipFile = deliverableZip()
File rawFile = new File(rawBom)
File outFile = new File(filteredBom)
Map bom = new JsonSlurper().parse(rawFile) as Map

List components = (bom.components ?: []) as List
// The file extension of a component's artifact: its purl's type qualifier (jar when the purl names none),
// the Maven types packaged as a jar giving jar.
final List JAR_TYPES = ['jar', 'bundle', 'ejb', 'ejb-client', 'fatjar', 'maven-plugin', 'test-jar', 'java-source', 'javadoc']
Closure extensionOf = { Map component ->
  def qualifier = (component.purl ?: '') =~ /[?&]type=([^&#]+)/
  String type = qualifier.find() ? qualifier.group(1) : 'jar'
  JAR_TYPES.contains(type) ? 'jar' : type
}
Map bySha256 = [:].withDefault { [] }
Map byName = [:].withDefault { [] }
components.each { component ->
  component.hashes?.findAll { it.alg == 'SHA-256' }?.each { bySha256[it.content.toLowerCase()].add(component) }
  // A name only matches a file of the same extension: a jar is never taken for the zip or the war of the same name.
  String extension = extensionOf(component)
  byName[extension + ':' + component.name].add(component)
  byName[extension + ':' + component.name + '-' + component.version].add(component)
}

Map kept = [:]
Map keptFrom = [:]
Map keptSha256 = [:]
List gaps = []
int deliveredCount = 0
List delivered = []
new ZipFile(zipFile).withCloseable { zip ->
  zip.entries().toList().findAll { entry ->
    !entry.directory && DELIVERED_EXTENSIONS.any { entry.name.endsWith(it) }
  }.each { entry ->
    String fileName = entry.name.substring(entry.name.lastIndexOf('/') + 1)
    List hashes = hashesOf { zip.getInputStream(entry) }
    delivered.add([
      name     : entry.name,
      hashes   : hashes,
      sha256   : hashes.find { it.alg == 'SHA-256' }.content,
      extension: fileName.substring(fileName.lastIndexOf('.') + 1),
      baseName : fileName.substring(0, fileName.lastIndexOf('.')),
    ])
  }
}
deliveredCount = delivered.size()

// A file no component of the graph identifies by SHA-256 may come from a zip of the graph unpacked into the delivered
// zip. It is identified by SHA-256 among the components, nested ones included, of the zip's published SBOM (its json
// artifact of classifier cyclonedx) when the zip has one, then among the zip's own entries, before any match by name:
// the zip's own file is what is delivered, whatever version the graph resolves under the same name. It is nested in
// the zip's component, which is then kept; its bom-ref is the zip's followed by '!/' and the file's path in the
// delivered zip. A file several zips hold goes to the first, in the graph's order, of the zips whose published SBOM
// lists it, else of the zips whose entries hold it; zips inside a zip are not opened.
Map artifactFiles = [:]
project.artifacts.findAll { !it.classifier && it.file }.each { artifact ->
  [artifact.version, artifact.baseVersion].each { version ->
    artifactFiles[artifact.groupId + ':' + artifact.artifactId + ':' + version + ':' + artifact.type] = artifact.file
  }
}
Closure publishedSbom = { Map component ->
  def request = new org.eclipse.aether.resolution.ArtifactRequest(
      new org.eclipse.aether.artifact.DefaultArtifact(component.group, component.name, 'cyclonedx', 'json', component.version),
      project.remoteProjectRepositories, null)
  File file
  try {
    file = session.container.lookup(org.eclipse.aether.RepositorySystem)
        .resolveArtifact(session.repositorySession, request).artifact.file
  } catch (org.eclipse.aether.resolution.ArtifactResolutionException e) {
    // An SBOM the repositories do not hold is the common case; any other failure is worth a warning.
    if (!e.results.every { result -> result.exceptions.every { it instanceof org.eclipse.aether.transfer.ArtifactNotFoundException } }) {
      log.warn('SBOM: the published SBOM of ' + component.purl + ' could not be resolved (' + e.message + '), its entries are searched instead')
    }
    return null
  }
  try {
    def parsed = new JsonSlurper().parse(file)
    if (parsed instanceof Map) {
      return parsed
    }
  } catch (groovy.json.JsonException ignored) {
  }
  log.warn('SBOM: the published SBOM of ' + component.purl + ' is not a JSON object, its entries are searched instead')
  null
}
Closure indexComponents
indexComponents = { def list, Map index ->
  (list instanceof List ? list : []).findAll { it instanceof Map }.each { inner ->
    (inner.hashes instanceof List ? inner.hashes : []).findAll {
      it instanceof Map && it.alg == 'SHA-256' && it.content instanceof String
    }.each {
      // A published component needs a type and a name; its copy is checked against the CycloneDX 1.6 schema when nested.
      if (inner.type instanceof String && inner.name instanceof String) {
        index.putIfAbsent(it.content.toLowerCase(), inner)
      }
    }
    indexComponents(inner.components, index)
  }
}
Closure contentOf = { Map component, File file ->
  Map publishedBySha = [:]
  Map entriesBySha = [:]
  Map published = publishedSbom(component)
  if (published != null) {
    try {
      indexComponents(published.components, publishedBySha)
    } catch (RuntimeException e) {
      log.warn('SBOM: the published SBOM of ' + component.purl + ' cannot be read (' + e + '), its entries are searched instead')
      publishedBySha.clear()
      published = null
    }
  }
  new ZipFile(file).withCloseable { zip ->
    zip.entries().toList().findAll { entry ->
      !entry.directory && DELIVERED_EXTENSIONS.any { entry.name.endsWith(it) }
    }.each { entry ->
      InputStream input = zip.getInputStream(entry)
      try {
        entriesBySha.putIfAbsent(digest('SHA-256', input), [entry: entry.name])
      } finally {
        input.close()
      }
    }
  }
  [component: component, published: published != null, publishedBySha: publishedBySha, entriesBySha: entriesBySha]
}
// The Maven coordinates a jar or a war declares in its single META-INF/maven pom.properties, if any.
Closure coordinatesOf = { InputStream input ->
  List found = []
  new java.util.zip.ZipInputStream(input).withCloseable { archive ->
    def entry
    while ((entry = archive.nextEntry) != null) {
      if (entry.name ==~ /META-INF\/maven\/[^\/]+\/[^\/]+\/pom\.properties/) {
        Properties properties = new Properties()
        properties.load(archive)
        found.add(properties)
      }
    }
  }
  Properties single = found.size() == 1 ? found[0] : null
  ['groupId', 'artifactId', 'version'].every { single?.getProperty(it) } ? single : null
}
// A component identified from the delivered file itself: its Maven coordinates when its pom.properties gives them,
// and the path of its entry in the zip when the zip's entries hold it.
Closure fromDeliveredFile = { ZipFile zip, Map file, Map content ->
  Properties coordinates = coordinatesOf(zip.getInputStream(zip.getEntry(file.name)))
  Map nested = [type: 'library', name: coordinates ? coordinates.getProperty('artifactId') : file.baseName]
  if (coordinates) {
    nested.group = coordinates.getProperty('groupId')
    nested.version = coordinates.getProperty('version')
    nested.purl = 'pkg:maven/' + nested.group + '/' + nested.name + '@' + nested.version + (file.extension == 'jar' ? '' : '?type=' + file.extension)
  }
  Map entry = content.entriesBySha[file.sha256]
  if (entry != null) {
    nested.properties = [[name: 'io.meeds:sbom:zip-entry', value: entry.entry]]
  }
  nested
}
// The fields a component copied from a published SBOM keeps.
final List COPIED_FIELDS = ['type', 'supplier', 'publisher', 'group', 'name', 'version', 'description', 'licenses',
                            'copyright', 'cpe', 'purl', 'externalReferences', 'properties']

List bySha = delivered.findAll { !bySha256[it.sha256].isEmpty() }
List notBySha = delivered.findAll { bySha256[it.sha256].isEmpty() }
List contents = []
if (!notBySha.isEmpty()) {
  contents = components.findAll { component ->
    extensionOf(component) == 'zip' && !(component.purl ?: '').contains('classifier=') &&
        artifactFiles[component.group + ':' + component.name + ':' + component.version + ':zip']
  }.collect { component ->
    contentOf(component, artifactFiles[component.group + ':' + component.name + ':' + component.version + ':zip'])
  }
}
List fromZips = []
List byNameOnly = []
notBySha.each { file ->
  Map content = contents.find { it.publishedBySha.containsKey(file.sha256) }
  Map found = content?.publishedBySha?.get(file.sha256)
  if (content == null) {
    content = contents.find { it.entriesBySha.containsKey(file.sha256) }
    found = content?.entriesBySha?.get(file.sha256)
  }
  if (content == null) {
    byNameOnly.add(file)
  } else {
    fromZips.add([file: file, content: content, found: found])
  }
}

// The files identified by SHA-256 come first, so that a component keeps the hashes of its identical file whatever
// the order of the zip's entries; another file identified as an already kept component is a gap, unless it is an
// identical copy of the kept file.
(bySha + byNameOnly).each { file ->
  boolean matchedByName = bySha256[file.sha256].isEmpty()
  List matches = matchedByName ? byName[file.extension + ':' + file.baseName].unique(false) : bySha256[file.sha256].unique(false)
  if (matches.size() == 1 && keptFrom.containsKey(matches[0]['bom-ref'])) {
    if (keptSha256[matches[0]['bom-ref']] == file.sha256) {
      return
    }
    gaps.add('duplicate file ' + file.name + ': ' + matches[0].purl + ' is already identified as ' + keptFrom[matches[0]['bom-ref']])
  } else if (matches.size() == 1) {
    if (matchedByName) {
      gaps.add('differing file ' + file.name + ': matched by name to ' + matches[0].purl + ', its SHA-256 differs')
    }
    Map component = matches[0] as Map
    component.hashes = file.hashes
    kept[component['bom-ref']] = component
    keptFrom[component['bom-ref']] = file.name
    keptSha256[component['bom-ref']] = file.sha256
  } else if (matches.isEmpty()) {
    gaps.add('unidentified file ' + file.name + ': no component with its SHA-256, nor in the zips of the graph, nor with its name and extension')
  } else {
    gaps.add('ambiguous file ' + file.name + ': ' + matches.collect { it.purl })
  }
}

new ZipFile(zipFile).withCloseable { zip ->
  fromZips.each { match ->
    Map file = match.file
    Map found = match.found
    Map zipComponent = match.content.component
    String nestedRef = zipComponent['bom-ref'] + '!/' + file.name
    Map nested
    if (found.entry == null) {
      nested = found.findAll { COPIED_FIELDS.contains(it.key) }
      if (nested.properties instanceof List) {
        nested.properties = nested.properties.findAll { it instanceof Map && it.name != 'io.meeds:sbom:zip-entry' }
      }
      if (!nested.properties) {
        nested.remove('properties')
      }
      nested['bom-ref'] = nestedRef
      nested.hashes = file.hashes
      // A copy the CycloneDX 1.6 schema refuses is replaced by the identification from the delivered file.
      Map single = [bomFormat: 'CycloneDX', specVersion: '1.6', version: 1, components: [nested]]
      List refused = new org.cyclonedx.parsers.JsonParser().validate(JsonOutput.toJson(single), org.cyclonedx.Version.VERSION_16)*.message
      if (!refused.isEmpty()) {
        log.warn('SBOM: the component of ' + file.name + ' in the published SBOM of ' + zipComponent.purl
            + ' is not valid CycloneDX 1.6 (' + refused.join('; ') + '), it is identified from the delivered file instead')
        nested = fromDeliveredFile(zip, file, match.content)
      }
    } else {
      nested = fromDeliveredFile(zip, file, match.content)
    }
    nested['bom-ref'] = nestedRef
    nested.hashes = file.hashes
    zipComponent.components = ((zipComponent.components ?: []) as List) + [nested]
    kept[zipComponent['bom-ref']] = zipComponent
  }
}
int nestedCount = fromZips.size()
contents.findAll { !it.published && kept.containsKey(it.component['bom-ref']) }.each {
  log.info('SBOM: ' + it.component.purl + ' has no published SBOM, the files it delivers are identified from its entries')
}

Map dependsOnByRef = ((bom.dependencies ?: []) as List).collectEntries { [(it.ref): (it.dependsOn ?: [])] }

// The kept components a node reaches, walking through the removed ones.
Closure keptReachedFrom = { String ref ->
  Set reached = new LinkedHashSet()
  Set visited = new HashSet()
  Deque pending = new ArrayDeque(dependsOnByRef[ref] ?: [])
  while (!pending.isEmpty()) {
    String next = pending.removeFirst()
    if (!visited.add(next)) {
      continue
    }
    if (kept.containsKey(next)) {
      reached.add(next)
    } else {
      pending.addAll(dependsOnByRef[next] ?: [])
    }
  }
  reached
}

String rawRootRef = bom.metadata?.component?.get('bom-ref')
String zipPurl = 'pkg:maven/' + project.groupId + '/' + project.artifactId + '@' + project.version + '?type=zip'
Map keptDependsOn = kept.keySet().collectEntries { ref -> [(ref): keptReachedFrom(ref)] }
// Every kept component is reachable from the zip: the zip depends on the components its packaging module
// reaches first, then, while some stay unreached, on one whose every unreached ancestor it also reaches
// (a component no other one reaches, or the first member of a cycle no component outside it reaches).
Map reachCache = [:]
Closure reachOf = { String ref ->
  reachCache.computeIfAbsent(ref) {
    Set reached = new HashSet()
    Deque pending = new ArrayDeque(keptDependsOn[ref])
    while (!pending.isEmpty()) {
      String next = pending.removeFirst()
      if (reached.add(next)) {
        pending.addAll(keptDependsOn[next])
      }
    }
    reached
  }
}
Set rootDependsOn = keptReachedFrom(rawRootRef)
Set reachedFromRoot = new HashSet(rootDependsOn)
rootDependsOn.each { reachedFromRoot.addAll(reachOf(it)) }
Set unreached = kept.keySet().findAll { !reachedFromRoot.contains(it) } as LinkedHashSet
while (!unreached.isEmpty()) {
  String entry = unreached.find { candidate ->
    unreached.every { other -> !reachOf(other).contains(candidate) || reachOf(candidate).contains(other) }
  }
  rootDependsOn.add(entry)
  reachedFromRoot.add(entry)
  reachedFromRoot.addAll(reachOf(entry))
  unreached.removeAll(reachedFromRoot)
}

bom.serialNumber = 'urn:uuid:' + UUID.randomUUID()
// The zip replaces the packaging module as root, keeping its publisher, licenses and references.
Map root = new LinkedHashMap(bom.metadata.component as Map)
root.type = 'application'
root['bom-ref'] = zipPurl
root.purl = zipPurl
root.hashes = hashesOf { new FileInputStream(zipFile) }
bom.metadata.component = root
bom.components = kept.values().toList()
bom.dependencies = [[ref: zipPurl, dependsOn: rootDependsOn.toList()]] +
    keptDependsOn.collect { ref, dependsOn -> [ref: ref, dependsOn: dependsOn.toList()] }

outFile.parentFile.mkdirs()
outFile.text = JsonOutput.prettyPrint(JsonOutput.toJson(bom))

// The published SBOM is checked against the CycloneDX 1.6 schema, and every reference of its graph against its components.
List invalid = new org.cyclonedx.parsers.JsonParser().validate(outFile, org.cyclonedx.Version.VERSION_16)*.message
Set knownRefs = (kept.keySet() + [zipPurl]) as Set
bom.dependencies.each { dependency ->
  ([dependency.ref] + dependency.dependsOn).findAll { !knownRefs.contains(it) }.each {
    invalid.add('dependency reference ' + it + ' names no component of the SBOM')
  }
}
if (!invalid.isEmpty()) {
  throw new IllegalStateException('SBOM: ' + outFile.name + ' is not a valid CycloneDX 1.6 SBOM: ' + invalid.join('; '))
}

log.info('SBOM: ' + zipFile.name + ' delivers ' + deliveredCount + ' files, ' + kept.size() + ' of the '
    + components.size() + ' components of the Maven graph kept, ' + nestedCount + ' files identified inside '
    + kept.values().count { it.components } + ' zips of the graph, ' + gaps.size() + ' gap(s), written to ' + outFile)
gaps.each { log.warn('SBOM: ' + it) }
if (FAIL_ON_GAPS && !gaps.isEmpty()) {
  throw new IllegalStateException('SBOM: ' + gaps.size() + ' gap(s) in the delivered files, see the warnings above')
}
